namespace Fanex.BetList.Core.Tests.Integration
{
    using System;
    using System.Collections.Generic;
    using System.Data;
    using System.IO;
    using System.Linq;
    using System.Text;
    using System.Windows.Forms;
    using System.Xml.Linq;
    using Fanex.BetList.Core.Tests.Integration.Data;
    using Fanex.BetList.Core.Tests.Integration.Interfaces;
    using Fanex.BetList.CoreToVerify.Wrap;
    using Newtonsoft.Json;
    using NPOI.HSSF.UserModel;
    using NPOI.SS.UserModel;

    /// <summary>
    /// Class ParallelRunner.
    /// </summary>
    public partial class ParallelRunner : Form
    {
        private ICoreHTMLBuilder _htmlBuilderToVerify;
        private DataSet _betData;
        private List<XElement> _sampleHTML;
        private IWorkbook _sampleWorkbook;
        private IWorkbook _workbookToVerify;

        public ParallelRunner()
        {
            InitializeComponent();
        }

        /// <summary>
        /// Handles the Click event of the btnHTMLRunTest control.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="e">The <see cref="EventArgs"/> instance containing the event data.</param>
        private void btnHTMLRunTest_Click(object sender, EventArgs e)
        {
            this.InitializeSampleHTML();
            this.InitializeData();

            if (_betData != null && _betData.Tables.Count == 2 && _sampleHTML != null)
            {
                _htmlBuilderToVerify = new CoreToVerifyHTML(_betData);

                this.RunHTMLTest();
            }
        }

        private void InitializeSampleHTML()
        {
            if (_sampleHTML == null)
            {
                XDocument xdoc = XDocument.Load("CBL.xml");
                _sampleHTML = xdoc.Descendants("Ticket").ToList();
            }
        }

        private void InitializeData()
        {
            if (_betData == null)
            {
                _betData = BetListDAO.GetBetListData();
            }
        }

        private void InitialzieSampleWorkbook(string filePath)
        {
            if (_sampleWorkbook == null)
            {
                using (StreamReader input = new StreamReader(filePath))
                {
                    _sampleWorkbook = new HSSFWorkbook(input.BaseStream);
                }
            }
        }

        private void InitializeWorkbookToVerify(string filePath)
        {
            if (_workbookToVerify == null)
            {
                using (StreamReader input = new StreamReader(filePath))
                {
                    _workbookToVerify = new HSSFWorkbook(input.BaseStream);
                }
            }
        }

        /// <summary>
        /// Runs the HTML test.
        /// </summary>
        private void RunHTMLTest()
        {
            int ticketCount = _betData.Tables[0].Rows.Count;

            if (ticketCount == _sampleHTML.Count && ticketCount == _htmlBuilderToVerify.TicketCount)
            {
                for (int i = 0; i < ticketCount; i++)
                {
                    string choiceToVerify = _htmlBuilderToVerify.BuildChoice(i, true);
                    string oddsToVerify = _htmlBuilderToVerify.BuildOdds(i);
                    string stakeToVerify = _htmlBuilderToVerify.BuildStake(i);
                    string statusToVerify = _htmlBuilderToVerify.BuildStatus(i, true);
                    string transToVerify = _htmlBuilderToVerify.BuildTrans(i);

                    XElement sourceTicket = this.GetSourceTicket(i);

                    if (sourceTicket != null)
                    {
                        string sourceChoice = sourceTicket.Element(XName.Get("Choice")).Value;
                        string sourceOdds = sourceTicket.Element(XName.Get("Odds")).Value;
                        string sourceStake = sourceTicket.Element(XName.Get("Stake")).Value;
                        string sourceStatus = sourceTicket.Element(XName.Get("Status")).Value;
                        string sourceTrans = sourceTicket.Element(XName.Get("Trans")).Value;

                        bool isChoiceIdentical = choiceToVerify == sourceChoice;
                        bool isOddsIdentical = oddsToVerify == sourceOdds;
                        bool isStakeIdentical = stakeToVerify == sourceStake;
                        bool isStatusIdentical = statusToVerify == sourceStatus;
                        bool isTransIdentical = transToVerify == sourceTrans;

                        if (isChoiceIdentical && isOddsIdentical && isStakeIdentical && isTransIdentical)
                        {
                            txtOutputPanel.Text += string.Format("{0} passed{1}", i, Environment.NewLine);
                        }
                        else
                        {
                            string failLog = this.CreateHTMLFailLog(i, isChoiceIdentical, isOddsIdentical, isStakeIdentical, isStatusIdentical, isTransIdentical);

                            txtOutputPanel.Text += failLog;
                        }
                    }
                }
            }
        }

        private XElement GetSourceTicket(int elementIndex)
        {
            XElement sourceTicket = _sampleHTML.ElementAt(elementIndex);

            if (sourceTicket != null && sourceTicket.Attribute("index").Value != elementIndex.ToString())
            {
                sourceTicket = _sampleHTML.Find(x => x.Attribute("index").Value == elementIndex.ToString());
            }

            return sourceTicket;
        }

        /// <summary>
        /// Creates the HTML fail log.
        /// </summary>
        /// <param name="entryIndex">Index of the entry.</param>
        /// <param name="isChoiceIdentical">If set to <c>true</c> [is choice identical].</param>
        /// <param name="isOddsIdentical">If set to <c>true</c> [is odds identical].</param>
        /// <param name="isStakeIdentical">If set to <c>true</c> [is stake identical].</param>
        /// <param name="isStatusIdentical">If set to <c>true</c> [is status identical].</param>
        /// <param name="isTransIdentical">If set to <c>true</c> [is trans identical].</param>
        /// <returns>Log string of failure.</returns>
        private string CreateHTMLFailLog(int entryIndex, bool isChoiceIdentical, bool isOddsIdentical, bool isStakeIdentical, bool isStatusIdentical, bool isTransIdentical)
        {
            StringBuilder logContent = new StringBuilder();

            logContent.AppendFormat("{0} failed{1}", entryIndex, Environment.NewLine);
            logContent.AppendLine("Data:");

            string ticketJson = _htmlBuilderToVerify.GetTicketJsonByIndex(entryIndex);
            logContent.AppendLine(ticketJson);

            logContent.AppendLine(string.Format("Choice: {0}{1}Odds: {2}{3}Stake: {4}{5}Status: {6}{7}Trans: {8}{9}", isChoiceIdentical, Environment.NewLine, isOddsIdentical, Environment.NewLine, isStakeIdentical, Environment.NewLine, isStatusIdentical, Environment.NewLine, isTransIdentical, Environment.NewLine));

            return logContent.ToString();
        }

        private void btnRunExcelTests_Click(object sender, EventArgs e)
        {
            this.InitializeData();
            this.InitialzieSampleWorkbook("OldBetList.xls");
            this.InitializeWorkbookToVerify("NewBetList.xls");

            if (_betData != null && _workbookToVerify != null && _sampleWorkbook != null)
            {
                this.RunExcelTest();
            }
        }

        /// <summary>
        /// Creates the excel fail log.
        /// </summary>
        /// <param name="entryIndex">Index of the entry.</param>
        /// <param name="isChoiceIdentical">If set to <c>true</c> [is choice identical].</param>
        /// <param name="isOddsIdentical">If set to <c>true</c> [is odds identical].</param>
        /// <param name="isStakeIdentical">If set to <c>true</c> [is stake identical].</param>
        /// <param name="isStatusIdentical">If set to <c>true</c> [is status identical].</param>
        /// <param name="isTransIdentical">If set to <c>true</c> [is trans identical].</param>
        /// <returns>Log string of failure.</returns>
        private string CreateExcelFailLog(int entryIndex, bool isChoiceIdentical, bool isOddsIdentical, bool isStakeIdentical, bool isStatusIdentical, bool isTransIdentical)
        {
            StringBuilder logContent = new StringBuilder();

            logContent.AppendFormat("{0} failed{1}", entryIndex, Environment.NewLine);
            logContent.AppendLine("Data:");

            string ticketJson = JsonConvert.SerializeObject(_betData.Tables[0].Rows[entryIndex]);
            logContent.AppendLine(ticketJson);

            logContent.AppendLine(string.Format("Choice: {0}{1}Odds: {2}{3}Stake: {4}{5}Status: {6}{7}Trans: {8}{9}", isChoiceIdentical, Environment.NewLine, isOddsIdentical, Environment.NewLine, isStakeIdentical, Environment.NewLine, isStatusIdentical, Environment.NewLine, isTransIdentical, Environment.NewLine));

            return logContent.ToString();
        }

        /// <summary>
        /// Runs the excel test.
        /// </summary>
        private void RunExcelTest()
        {
            bool isWorkBookIdentical = ObjectComparer<IWorkbook>.Compare(_sampleWorkbook, _workbookToVerify);
            if (!isWorkBookIdentical)
            {
                txtOutputPanel.Text = "Whole workbook is different!" + Environment.NewLine;
            }

            int ticketCount = _betData.Tables[0].Rows.Count;
            HSSFSheet sampleSheet = (HSSFSheet)_sampleWorkbook.GetSheet("BetList");
            HSSFSheet sheetToVerify = (HSSFSheet)_workbookToVerify.GetSheet("BetList");
            bool isWorksheetIdentical = ObjectComparer<HSSFSheet>.Compare(sampleSheet, sheetToVerify);

            if (!isWorksheetIdentical)
            {
                txtOutputPanel.Text += "Whole sheet is different!" + Environment.NewLine;
            }

            if (ticketCount == sheetToVerify.LastRowNum + 1 && sheetToVerify.LastRowNum == sampleSheet.LastRowNum)
            {
                for (int i = 0; i < ticketCount; i++)
                {
                    HSSFRow sampleRow = (HSSFRow)sampleSheet.GetRow(i);
                    HSSFRow rowToVerify = (HSSFRow)sheetToVerify.GetRow(i);

                    bool isRowIdentical = ObjectComparer<HSSFRow>.Compare(sampleRow, rowToVerify);

                    if (!isRowIdentical)
                    {
                        txtOutputPanel.Text += string.Format("Whole row #{0} is different!{1}", i, Environment.NewLine);
                    }

                    bool isChoiceIdentical = ObjectComparer<HSSFCell>.Compare((HSSFCell)rowToVerify.GetCell(0), (HSSFCell)sampleRow.GetCell(0));
                    bool isOddsIdentical = ObjectComparer<ICell>.Compare(rowToVerify.GetCell(1), sampleRow.GetCell(1));
                    bool isStakeIdentical = ObjectComparer<ICell>.Compare(rowToVerify.GetCell(2), sampleRow.GetCell(2));
                    bool isStatusIdentical = ObjectComparer<ICell>.Compare(rowToVerify.GetCell(3), sampleRow.GetCell(3));
                    bool isTransIdentical = ObjectComparer<ICell>.Compare(rowToVerify.GetCell(4), sampleRow.GetCell(4));

                    if (isChoiceIdentical && isOddsIdentical && isStakeIdentical && isStatusIdentical && isTransIdentical)
                    {
                        txtOutputPanel.Text += string.Format("{0} passed{1}", i, Environment.NewLine);
                    }
                    else
                    {
                        string failLog = this.CreateExcelFailLog(i, isChoiceIdentical, isOddsIdentical, isStakeIdentical, isStatusIdentical, isTransIdentical);

                        txtOutputPanel.Text += failLog;
                    }
                }
            }
        }

        private bool Compare(ICell source, ICell dest)
        {
            if (source != null && dest != null)
            {
                return source.BooleanCellValue == dest.BooleanCellValue;
            }

            return false;
        }
    }
}
